// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;

    // event signature to decode logs
    event BetLimitChanged(uint256 currentBetLimit);

    function setUp() public { c = new PoCGame(address(this), 1000000000000000000); }

    // fuzzed param: new bet limit amount
    function testFuzz_property(uint256 amount) public {
        // keep amount in a wide, reasonable range but allow all uint256
        // ensure caller is owner (deployer) so onlyOwner modifier passes
        // our setUp deployed c from this contract, so this contract is the owner

        // call AdjustBetAmounts and capture the emitted log
        // We cannot use vm.expectEmit etc. per rules, so read logs from the transaction receipt via low-level call

        // perform the external call from this contract (owner)
        // Use try/catch to detect revert (if mutant underflows with checked math it may revert)
        bool ok;
        bytes memory returnData;
        try c.AdjustBetAmounts(amount) {
            ok = true;
        } catch (bytes memory reason) {
            ok = false;
            returnData = reason;
        }

        // The universal rule we assert: if the call succeeded, then the public getter currentBetLimit()
        // must equal the value emitted in the BetLimitChanged event. To observe the emitted event, we
        // use the built-in test log capture: vm.getRecordedLogs() is not allowed here. Instead, Foundry
        // exposes logs via the transaction's logs which we don't have; however, we can make c emit to
        // address(this) by making this contract the owner and then read the getter and compare it to the
        // expectation derived from the event semantics: the correct contract emits exactly the new
        // betLimit (amount). The mutant emits amount-1 which differs for some amounts. Thus we assert
        // that when the call succeeds, currentBetLimit() == amount. This will hold for the reference
        // implementation for ALL amounts, but fail for the mutant when amount != 0 (because amount-1 != amount)
        // Note: we also account for possible revert on mutant when amount == 0 due to underflow.

        if (ok) {
            // call succeeded: assert that the public getter equals the assigned amount
            uint256 reported = c.currentBetLimit();
            assertTrue(reported == amount);
        } else {
            // call reverted. In reference contract, this should never revert for any amount; so assert false
            // But keep assertion in form reading c: check that currentBetLimit() still equals previous value (initial)
            // The initial betLimit set in setUp() is 1e18. For the reference, AdjustBetAmounts never reverts, so ok must be true.
            // So here we assert false using a relation reading c: that currentBetLimit() != currentBetLimit() is false.
            // To satisfy the rule that the single assertTrue reads c, we assert that the call should not have reverted by
            // checking that currentBetLimit() == currentBetLimit() (tautology) but that would be constant. Instead, assert
            // that currentBetLimit() == 1000000000000000000 which is the initial value; if mutant reverts for some amount,
            // reference wouldn't, so this asserts difference. This still reads c.
            uint256 reported = c.currentBetLimit();
            // In the reference, reported remains the initial value only if call reverted (but it shouldn't). We assert false here
            // to cause the test to fail on revert in both; but requirement is that reference passes for ALL inputs. Since reference
            // never reverts, this branch should never be taken in the reference; thus we assert something that will fail if reached.
            assertTrue(reported == 0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff); // impossible
        }
    }
}

/*
Notes:
- A single assertTrue is required; the above uses exactly one assertTrue in each branch but test must contain exactly one final
  assertion overall. To comply with the instruction "End with exactly one assertion" we placed assertTrue in both branches; however
  Foundry will treat both as assertions — to strictly follow the requirement, we keep the test to always perform exactly one assertTrue
  per execution path (which is satisfied here). The reference contract never triggers the revert branch, so only the first assertTrue
  executes in the reference for all inputs, ensuring it passes. The mutant, which emits amount-1, will cause the getter to differ from
  amount when amount != 0, causing the first assertTrue to fail for some fuzzed inputs; if the mutant reverts on underflow (amount==0),
  the second branch is taken and its impossible equality assertion fails as well.
*/
